def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    # Extract compact views of history
    last_my, last_opp = history[-1]
    opp_c = 0
    my_c = 0
    for a, b in history:
        if b == 'C':
            opp_c += 1
        if a == 'C':
            my_c += 1

    # Terminal exploitation: if opponent is highly cooperative, take advantage.
    if n >= 96:
        if opp_c * 100 >= n * 60:
            return 'D'
        if opp_c * 100 <= n * 30:
            return 'D'
        return 'C'

    # Early game: cooperate to establish mutual cooperation.
    if n < 6:
        return 'C'

    # Compute recent statistics.
    recent = history[-10:]
    opp_recent_c = 0
    opp_recent_d = 0
    my_recent_d = 0
    for a, b in recent:
        if b == 'C':
            opp_recent_c += 1
        else:
            opp_recent_d += 1
        if a == 'D':
            my_recent_d += 1

    # Detect always-defect / sustained defection.
    if n >= 10:
        if opp_c == 0:
            return 'D'
        if opp_recent_d >= 8:
            # Very likely a defector; defect but occasionally test.
            if rng.random() < 0.03:
                return 'C'
            return 'D'

    # Detect near-always-cooperate: exploit moderately while preserving cooperation.
    if n >= 20 and opp_c * 100 >= n * 92:
        # Mostly cooperate, but sometimes defect to increase score.
        # Keep the defection rate low to avoid triggering punishment spirals.
        if rng.random() < 0.18:
            return 'D'
        return 'C'

    # If opponent just defected:
    if last_opp == 'D':
        # Forgiveness: if opponent's overall cooperation is high, forgive quickly.
        if opp_c * 100 >= n * 75:
            # Occasional defection (to punish/exploit) but usually return to C.
            # If we defected last round, cooperate to restore CC.
            if last_my == 'D':
                return 'C'
            # If opponent defected after we cooperated, retaliate once.
            if my_recent_d == 0:
                return 'D'
            # Forgive with moderate probability.
            if rng.random() < 0.55:
                return 'C'
            return 'D'

        # Moderately cooperative opponent: retaliate but forgive after a couple rounds.
        if opp_recent_d >= 4:
            return 'D'
        if opp_c * 100 >= n * 45:
            # Tit-for-tat-ish: defect once, then cooperate.
            if last_my == 'D':
                return 'C'
            if rng.random() < 0.5:
                return 'D'
            return 'C'
        # Low cooperation: punish more.
        if rng.random() < 0.75:
            return 'D'
        return 'C'

    # Opponent just cooperated.
    # If we defected last round, return to cooperation to restore mutual CC,
    # unless we're in an exploitation streak against a very cooperative opponent.
    if last_my == 'D':
        if opp_c * 100 >= n * 92 and n > 30:
            # Continue occasional exploitation, but reestablish CC sometimes.
            if rng.random() < 0.5:
                return 'D'
            return 'C'
        return 'C'

    # Against a very defective opponent, defect.
    if n >= 10 and opp_c * 100 <= n * 25:
        if rng.random() < 0.9:
            return 'D'
        return 'C'

    # Default: cooperate.
    return 'C'
